// Uebersetzt die Auswahl im Formular in Ziel-Workflow und Modus.
// Die Ziel-Workflows haben dafuer je einen Trigger "Testlauf-Start".
const s = String($json.Schritt || '').trim();
const ziele = {
  'WF05 Affiliate-Pipeline auffuellen': { workflow_id: 'WF05_ID', modus: 'erstellen' },
  'WF08 Affiliate-Pin erzeugen':        { workflow_id: 'WF08_ID', modus: 'erstellen' },
  'WF07 Buch-Pins erzeugen':            { workflow_id: 'WF07_ID', modus: 'erstellen' },
  'WF06 Freigabe-Mail senden':          { workflow_id: 'WF06_ID', modus: 'mail' },
  'WF07 Buch-Pins posten':              { workflow_id: 'WF07_ID', modus: 'posten' },
  'WF08 Affiliate-Pin posten':          { workflow_id: 'WF08_ID', modus: 'posten' },
  'WF09 Etsy-Produkte naechstes Buch':  { workflow_id: 'WF09_ID', modus: 'auto' },
  'WF02 Buch ab Produktion fortsetzen': { workflow_id: 'WF02_ID', modus: 'fortsetzen', braucht_id: true },
  'WF03 Buch ab Cover fortsetzen':      { workflow_id: 'WF03_ID', modus: 'fortsetzen', braucht_id: true }
};
const z = ziele[s];
if (!z) throw new Error('Unbekannter Schritt: ' + s);
const buchId = String($json['Buch-ID'] || '').trim();
if (z.braucht_id && !buchId) throw new Error('Fuer "' + s + '" bitte eine Buch-ID angeben.');
const out = { workflow_id: z.workflow_id, modus: z.modus, schritt: s, quelle: 'testlauf', gestartet_am: new Date().toISOString() };
if (buchId) out.buch_id = buchId;
return [{ json: out }];
